// Byline, "Last updated" date and Article JSON-LD for blog articles.
// Dates come from data/article-dates.json (generated by scripts/article-dates.mjs).

import { site } from "@/data/config";
import articleDates from "@/data/article-dates.json";

const formatDate = (iso) =>
  new Date(`${iso}T00:00:00Z`).toLocaleDateString("en-AU", {
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  });

export default function ArticleMeta({ slug, headline }) {
  const dates = articleDates[slug];
  if (!dates) {
    throw new Error(
      `No dates for blog article "${slug}". Run: node scripts/article-dates.mjs`
    );
  }

  const url = `${site.url}/blog/${slug}`;
  const org = { "@type": "Organization", name: "Adelaide Roofers", url: site.url };
  const articleJsonLd = {
    "@context": "https://schema.org",
    "@type": "Article",
    headline,
    author: org,
    publisher: org,
    datePublished: dates.datePublished,
    dateModified: dates.dateModified,
    mainEntityOfPage: { "@type": "WebPage", "@id": url },
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(articleJsonLd) }}
      />
      <p className="mt-4 font-body text-sm text-ink/55">
        By the Adelaide Roofers team
        <span aria-hidden="true"> · </span>
        Last updated <time dateTime={dates.dateModified}>{formatDate(dates.dateModified)}</time>
      </p>
    </>
  );
}
